//! Authored source/semantic judgments, no provider, gold or storage claims.
use lightog_core::{
    common::{canonical_hash as hash, text_sha},
    knowledge_build, source_learning_v1 as learning,
    support_selection, candidate_staging_v1 as staging,
};
use serde_json::{json, Value};

fn fixture() -> Value {
    let text="🚀 Mode Alpha.\nIt leaves the index unchanged.\nIt refers to mode Alpha.\nIf the same file is unstaged, abort.\n";
    let digest = text_sha(text);
    let size = text.encode_utf16().count();
    let snapshot = json!({"base_ref":"source_learning_authored","source_epoch":0,"graph_revision":null,"sources":[{"source_ref":"src","source_revision":"r1","original_sha256":digest,"text_sha256":digest,"parser_version":"authored/1"}]});
    let mut at = 0;
    let fragments:Vec<_>=text.split_inclusive('\n').zip(["mode","assertion","antecedent","condition"]).map(|(quote,id)|{let start=at;at+=quote.encode_utf16().count();json!({"id":id,"origin":"SOURCE_FRAGMENT","source_ref":"src","source_revision":"r1","block_ref":"b","text_sha256":digest,"span":{"start":start,"end":at,"quote":quote,"offset_unit":"utf16_code_unit"},"claim_refs":[],"role":"PRIMARY"})}).collect();
    let es = json!({"contract_version":"lightog-demand/0.1","evidence_set_id":"es","snapshot":snapshot,"fragments":fragments});
    let context = json!({"examples":{"es":es},"source_texts":[{"source_ref":"src","source_revision":"r1","text":text,"original_sha256":digest,"parser_version":"authored/1","blocks":[{"block_ref":"b","start":0,"end":size}]}],"authority":{"requests":[],"allowed_snapshots":[snapshot],"claims":[],"receipts":[],"scope_bindings":[],"entities":[],"predicate_refs":[],"user_definitions":[],"groups":[],"entity_links":[]}});
    let question = "How does mode Alpha affect the index?";
    let runtime = json!({"current_snapshot":snapshot,"grants":[{"request_ref":"request_authored","question_sha256":text_sha(question),"base_ref":snapshot["base_ref"],"source_epoch":0,"access_mode":"LEARN","learning_requested":true}],"persisted_job_sha256":null,"persisted_revision":0,"support_hold_candidate_sha256":[],"graph_record_sha256":null,"commit_record_sha256":null,"index_record_sha256":null,"index_payload_sha256":null});
    json!({"contract_version":learning::VERSION,"request":{"request_ref":"request_authored","raw_question":question,"cq_seeds":[{"seed_id":"seed_authored","text":question}],"kind":"DISCOVERY","policy_version":"source-learning-product-candidate-mvp-v1"},"evidence_set":es,"source_gap":null,"context":context,"runtime":runtime})
}
fn gate(f: &Value, unit: &str, required: bool) -> Value {
    let es = &f["evidence_set"];
    let context = &f["context"];
    let prepared=knowledge_build::prepare_extract(&json!({"evidence_set_ref":es["evidence_set_id"],"cq_guidance":f["request"]["raw_question"],"trusted_context":context})).unwrap();
    let mut raw = json!({"entities":[{"local_id":"Alpha","surface":"Alpha","type_label":null,"mention_evidence_id":"mode"}],"candidates":[{"kind":"ATTRIBUTE","subject_local_id":"Alpha","predicate":{"label":"index effect","description":"Effect on index state","evidence_ids":["assertion"]},"object":{"entity_local_id":null,"typed_value":{"kind":"STRING","value":"unchanged"}},"direction":"NONE","description":"Mode Alpha leaves the index unchanged.","keywords":["index"],"qualifiers":{"scope":"Mode Alpha","modality":"REPORTED","negated":false,"unit":null,"effective_time":null},"conditions":[],"support_roles":{"assertion":["assertion"],"subject_scope":["mode"],"antecedent":["antecedent"],"condition":[]}}]});
    raw["entities"][0]["mention_occurrence"] = json!(1);
    let m=support_selection::execute(if required{"materialize_required_occurrence_v1"}else{"materialize_occurrence_v1"},&json!({"prepared":prepared,"trusted_context":context,"raw":raw,"unit_id":unit,"max_candidates":8})).unwrap();
    assert_eq!(m["candidates"].as_array().unwrap().len(), 1);
    json!({"contract_version":staging::VERSION,"candidates":m["candidates"],"prepared":prepared,"trusted_context":context,"receipts":m["receipts"],"context_evidence_ids":["mode","assertion","antecedent","condition"],"max_context_utf16":12000})
}

fn payload(f: &Value, j: &Value) -> Value {
    let mut runtime = f["runtime"].clone();
    runtime["persisted_job_sha256"] = j["job_sha256"].clone();
    runtime["persisted_revision"] = j["revision"].clone();
    json!({"contract_version":learning::VERSION,"job":j,"context":f["context"],"runtime":runtime})
}
fn job(f: &Value) -> Value {
    learning::execute("create", f).unwrap()["job"].clone()
}
fn validating(f: &Value) -> Value {
    let mut j = job(f);
    for stage in ["RETRIEVING", "EXTRACTING", "VALIDATING"] {
        let mut p = payload(f, &j);
        p["next_stage"] = json!(stage);
        j = learning::execute("step", &p).unwrap()["job"].clone();
    }
    let mut p=payload(f,&j);p["attempt_id"]=json!("extract_mvp");p["phase"]=json!("EXTRACTION");p["request_sha256"]=json!("b".repeat(64));
    j=learning::execute("begin_attempt",&p).unwrap()["job"].clone();
    p=payload(f,&j);p["attempt_id"]=json!("extract_mvp");p["outcome"]=json!("RETURNED");p["request_id"]=json!("actual_authored_extraction");p["response_sha256"]=json!("c".repeat(64));
    learning::execute("finish_attempt",&p).unwrap()["job"].clone()
}

fn prepare(f:&Value,j:&Value,base:Value,unit:&str)->Value{let mut p=payload(f,j);p["gate_input"]=gate(f,unit,true);p["base_graph"]=base.clone();if !base.is_null(){p["runtime"]["graph_record_sha256"]=json!(hash(&base));}learning::execute("prepare_commit",&p).unwrap()}
fn receipt(plan:&Value)->Value{json!({"contract_version":learning::COMMIT_VERSION,"receipt_ref":"actual_host_receipt_authored","task_ref":plan["task_ref"],"idempotency_key":plan["idempotency_key"],"commit_plan_sha256":plan["plan_sha256"],"input_snapshot_sha256":plan["input_snapshot_sha256"],"base_graph_digest":plan["base_graph_digest"],"output_graph_revision":plan["output_graph_revision"],"output_graph_digest":plan["output_graph_digest"],"write_set_sha256":plan["write_set_sha256"],"index_state":"PENDING"})}
fn commit(f:&Value,prepared:&Value)->(Value,Value){let r=receipt(&prepared["commit_plan"]);let mut p=payload(f,&prepared["job"]);p["commit_plan"]=prepared["commit_plan"].clone();p["persisted_write_set"]=prepared["write_set"].clone();p["receipt"]=r.clone();p["runtime"]["graph_record_sha256"]=json!(hash(&prepared["write_set"]));p["runtime"]["commit_record_sha256"]=json!(hash(&r));let j=learning::execute("confirm_commit",&p).unwrap()["job"].clone();(j,r)}
fn read_context(f:&Value,bundle:&Value)->Value{let mut context=f["context"].clone();context["authority"]["allowed_snapshots"]=json!([bundle["read_snapshot"]]);context}
fn projection(f:&Value,bundle:&Value)->Value{let mut runtime=f["runtime"].clone();runtime["current_snapshot"]=bundle["read_snapshot"].clone();runtime["graph_record_sha256"]=json!(hash(bundle));learning::execute("project_read",&json!({"contract_version":learning::VERSION,"write_set":bundle,"read_snapshot":bundle["read_snapshot"],"context":read_context(f,bundle),"runtime":runtime})).unwrap()}
fn lexical_payload(projection:&Value)->Value{let mut records=vec![];let mut seen=std::collections::BTreeSet::new();for es in projection["evidence_sets"].as_array().unwrap(){for f in es["fragments"].as_array().unwrap(){if seen.insert(f["id"].as_str().unwrap()){records.push(json!({"id":format!("doc:{}",f["id"].as_str().unwrap()),"kind":"DOCUMENT","text":f["span"]["quote"],"entity_refs":[],"evidence_ids":[f["id"]],"status":"SOURCE","profile":null,"embedding":null}));}}}let mut owner=std::collections::BTreeMap::new();for p in projection["p2Build"]["profiles"].as_array().unwrap(){let id=format!("profile:{}",p["id"].as_str().unwrap());owner.insert(p["owner_id"].as_str().unwrap(),id.clone());let ids:Vec<_>=p["evidence_refs"].as_array().unwrap().iter().map(|r|r["evidence_id"].clone()).collect();records.push(json!({"id":id,"kind":if p["kind"]=="ATTRIBUTE"{"RELATION"}else{p["kind"].as_str().unwrap()},"text":p["text"],"entity_refs":p["entity_refs"],"evidence_ids":ids,"status":"DISCOVERY_HINT","profile":null,"embedding":null}));}let mut edges=vec![];for s in projection["p2Build"]["graph"]["statements"].as_array().unwrap(){let ids:Vec<_>=s["evidence_refs"].as_array().unwrap().iter().map(|r|r["evidence_id"].clone()).collect();edges.push(json!({"id":format!("edge:{}:{}",s["id"].as_str().unwrap(),s["subject_id"].as_str().unwrap()),"source_record_id":owner[s["id"].as_str().unwrap()],"target_record_id":owner[s["subject_id"].as_str().unwrap()],"evidence_ids":ids,"status":"DISCOVERY_HINT"}));}json!({"contract_version":"lightog-hybrid-retrieval/0.1","question":"index behavior","queries":{"document":"index behavior","entity":"Alpha","relation":"index effect"},"snapshot":projection["snapshot"],"trusted_index":{"records":records,"edges":edges,"manifests":[],"context":projection["context"],"evidence_token_counts":{},"tokenizer":null},"query_vectors":[],"rerank":null,"options":{"channel_top_k":20,"result_top_k":12,"rrf_k":60,"max_graph_neighbors":12,"max_context_utf16":16000,"max_context_tokens":null,"min_cosine":0.0}})}

#[test]fn staging_is_mechanical_without_positive_or_review_fields(){let f=fixture();let g=gate(&f,"staged",true);let out=staging::execute("stage",&g).unwrap();assert_eq!(out["semantic_status"],"CANDIDATE_UNREVIEWED");assert_eq!(out["semantic_review_performed"],false);assert!(out.get("eligible_candidates").is_none());assert!(out.get("review_receipt").is_none());assert_eq!(out["staged_candidates"],g["candidates"]);let mut bad=g.clone();bad["review_output"]=json!({});assert!(staging::execute("stage",&bad).is_err());let optional=gate(&f,"optional",false);assert_eq!(staging::execute("stage",&optional).unwrap_err().code,"CANDIDATE_STAGING_REQUIRED_PROPOSAL_CONTRACT");}
#[test]fn mvp_commit_and_projection_never_upgrade_candidates_to_facts(){let f=fixture();let p=prepare(&f,&validating(&f),Value::Null,"commit");assert!(p["commit_plan"].get("accepted_candidate_bindings").is_none());assert_eq!(p["commit_plan"]["staged_candidate_bindings"].as_array().unwrap().len(),1);assert_eq!(p["write_set"]["graph_trust"]["review_performed"],false);let(pending,_)=commit(&f,&p);assert_eq!(pending["stage"],"INDEX_PENDING");let read=projection(&f,&p["write_set"]);assert_eq!(read["graph_trust"]["semantic_status"],"CANDIDATE_UNREVIEWED");assert_eq!(read["context"]["authority"]["claims"],json!([]));assert_eq!(read["context"]["authority"]["receipts"],json!([]));for profile in read["p2Build"]["profiles"].as_array().unwrap(){assert_eq!(profile["status"],"DISCOVERY_HINT");}}
#[test]fn invalid_source_receipt_or_candidate_is_not_stageable(){let f=fixture();let g=gate(&f,"invalid",true);for mode in 0..4{let mut bad=g.clone();match mode{0=>bad["candidates"][0]["snapshot"]["source_epoch"]=json!(99),1=>bad["receipts"][0]["candidate_sha256"]=json!("0".repeat(64)),2=>bad["trusted_context"]["source_texts"][0]["text"]=json!("replaced private text"),_=>bad["prepared"]["payload"]["evidence_menu"][0]["quote"]=json!("wrong")};assert!(staging::execute("stage",&bad).is_err(),"mode {mode}");}}
#[test]fn new_policy_cannot_borrow_old_review_and_requires_returned_extraction(){let f=fixture();let j=job(&f);let mut advanced=j;for stage in ["RETRIEVING","EXTRACTING","VALIDATING"]{let mut p=payload(&f,&advanced);p["next_stage"]=json!(stage);advanced=learning::execute("step",&p).unwrap()["job"].clone();}let mut p=payload(&f,&advanced);p["gate_input"]=gate(&f,"noattempt",true);p["base_graph"]=Value::Null;assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_MVP_EXTRACTION_RETURNED_REQUIRED");p=payload(&f,&validating(&f));p["gate_input"]=gate(&f,"wrongprotocol",true);p["gate_input"]["contract_version"]=json!("lightog-semantic-review/0.4");p["base_graph"]=Value::Null;assert_eq!(learning::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_GATE_BINDING_INVALID");}
#[test]fn source_withdrawal_and_staging_tamper_block_read_reuse(){let f=fixture();let prepared=prepare(&f,&validating(&f),Value::Null,"drift");let mut bundle=prepared["write_set"].clone();bundle["builds"][0]["staging_metadata"]["semantic_status"]=json!("SUPPORTED");let body=json!({"contract_version":bundle["contract_version"],"source_scope":bundle["source_scope"],"builds":bundle["builds"]});let d=hash(&body);bundle["graph_digest"]=json!(d);bundle["output_graph_revision"]=json!(format!("slg_{}",&d[..32]));bundle["read_snapshot"]["graph_revision"]=bundle["output_graph_revision"].clone();let mut runtime=f["runtime"].clone();runtime["current_snapshot"]=bundle["read_snapshot"].clone();runtime["graph_record_sha256"]=json!(hash(&bundle));let p=json!({"contract_version":learning::VERSION,"write_set":bundle,"read_snapshot":bundle["read_snapshot"],"context":read_context(&f,&bundle),"runtime":runtime});assert_eq!(learning::execute("project_read",&p).unwrap_err().code,"SOURCE_LEARNING_STAGING_CHANGED");let mut p=p;p["write_set"]=prepared["write_set"].clone();p["read_snapshot"]=prepared["write_set"]["read_snapshot"].clone();p["runtime"]["current_snapshot"]["source_epoch"]=json!(1);assert!(learning::execute("project_read",&p).is_err());}
#[test]fn lexical_index_requires_real_payload_validation_and_ack_replay_before_completed(){let f=fixture();let prepared=prepare(&f,&validating(&f),Value::Null,"index_authored");let bundle=&prepared["write_set"];let (pending,receipt)=commit(&f,&prepared);let projected=projection(&f,bundle);let validation=lexical_payload(&projected);let mut p=payload(&f,&pending);p["context"]=read_context(&f,bundle);p["runtime"]["current_snapshot"]=bundle["read_snapshot"].clone();p["runtime"]["graph_record_sha256"]=json!(hash(bundle));p["runtime"]["commit_record_sha256"]=json!(hash(&receipt));p["runtime"]["index_payload_sha256"]=json!(hash(&validation["trusted_index"]));p["receipt"]=receipt.clone();p["write_set"]=bundle.clone();p["index_ref"]=json!("actual_index_authored");p["validation_payload"]=validation;let ready=learning::execute("prepare_index",&p).unwrap();assert_eq!(ready["index_ack"]["mode"],"LEXICAL");assert_eq!(ready["index_ack"]["vectors_completed"],0);p.as_object_mut().unwrap().remove("index_ref");p["index_ack"]=ready["index_ack"].clone();p["projection_receipt"]=ready["projection_receipt"].clone();p["runtime"]["index_record_sha256"]=json!(hash(&ready["index_ack"]));let completed=learning::execute("confirm_index",&p).unwrap();assert_eq!(completed["job"]["stage"],"COMPLETED");let mut forged=p.clone();forged["index_ack"]["records_total"]=json!(999);forged["runtime"]["index_record_sha256"]=json!(hash(&forged["index_ack"]));assert_eq!(learning::execute("confirm_index",&forged).unwrap_err().code,"SOURCE_LEARNING_INDEX_ACK_REPLAY_CHANGED");let mut missing=p;missing["validation_payload"]["trusted_index"]["records"].as_array_mut().unwrap().pop();missing["runtime"]["index_payload_sha256"]=json!(hash(&missing["validation_payload"]["trusted_index"]));assert_eq!(learning::execute("confirm_index",&missing).unwrap_err().code,"SOURCE_LEARNING_INDEX_RECORDS_CHANGED");}

#[test]fn mechanically_wellformed_but_semantically_wrong_text_remains_unreviewed(){let f=fixture();let mut g=gate(&f,"wrong-narrative",true);let mut raw=g["receipts"][0]["occurrence_support_raw"].clone();raw["candidates"][0]["description"]=json!("Mode Alpha erases every unrelated file on every machine.");raw["candidates"][0]["qualifiers"]["negated"]=json!(true);let m=support_selection::execute("materialize_required_occurrence_v1",&json!({"prepared":g["prepared"],"trusted_context":g["trusted_context"],"raw":raw,"unit_id":"wrong-narrative-rematerialized","max_candidates":8})).unwrap();assert_eq!(m["candidates"].as_array().unwrap().len(),1);g["candidates"]=m["candidates"].clone();g["receipts"]=m["receipts"].clone();let staged=staging::execute("stage",&g).unwrap();assert_eq!(staged["staged_candidates"][0]["qualifiers"]["negated"],true);assert_eq!(staged["semantic_status"],"CANDIDATE_UNREVIEWED");assert_eq!(staged["semantic_support_certified"],false);assert!(staged.get("eligible_candidates").is_none());}

#[test]fn multiple_candidates_replay_after_archive_canonical_sort(){let f=fixture();let mut g=gate(&f,"multi",true);let mut raw=g["receipts"][0]["occurrence_support_raw"].clone();let mut second=raw["candidates"][0].clone();second["object"]["typed_value"]["value"]=json!("other authored possible interpretation");second["description"]=json!("A second unreviewed interpretation of the index state.");raw["candidates"].as_array_mut().unwrap().push(second);let m=support_selection::execute("materialize_required_occurrence_v1",&json!({"prepared":g["prepared"],"trusted_context":g["trusted_context"],"raw":raw,"unit_id":"multi-two","max_candidates":8})).unwrap();assert_eq!(m["candidates"].as_array().unwrap().len(),2);g["candidates"]=m["candidates"].clone();g["candidates"].as_array_mut().unwrap().reverse();g["receipts"]=m["receipts"].clone();let j=validating(&f);let mut p=payload(&f,&j);p["gate_input"]=g;p["base_graph"]=Value::Null;let result=learning::execute("prepare_commit",&p).unwrap();assert_eq!(result["write_set"]["builds"][0]["graph"]["candidate_archive"].as_array().unwrap().len(),2);let read=projection(&f,&result["write_set"]);assert_eq!(read["graph_trust"]["usage"],"NAVIGATION_ONLY");}

#[test]fn extra_mechanical_quarantine_receipt_is_not_promoted_or_staged(){let f=fixture();let mut g=gate(&f,"quarantine-extra",true);let mut raw=g["receipts"][0]["occurrence_support_raw"].clone();let mut bad=raw["candidates"][0].clone();bad["subject_local_id"]=json!("nonexistent-subject");raw["candidates"].as_array_mut().unwrap().push(bad);let m=support_selection::execute("materialize_required_occurrence_v1",&json!({"prepared":g["prepared"],"trusted_context":g["trusted_context"],"raw":raw,"unit_id":"quarantine-extra-batch","max_candidates":8})).unwrap();assert_eq!(m["candidates"].as_array().unwrap().len(),1);assert_eq!(m["receipts"].as_array().unwrap().len(),2);g["candidates"]=m["candidates"].clone();g["receipts"]=m["receipts"].clone();let out=staging::execute("stage",&g).unwrap();assert_eq!(out["staged_candidates"].as_array().unwrap().len(),1);assert_eq!(out["staging_receipt"]["candidate_bindings"].as_array().unwrap().len(),1);let j=validating(&f);let mut p=payload(&f,&j);p["gate_input"]=g;p["base_graph"]=Value::Null;let committed=learning::execute("prepare_commit",&p).unwrap();assert_eq!(committed["write_set"]["builds"][0]["graph"]["candidate_archive"].as_array().unwrap().len(),1);}
